/**
 * DST OAuth2 token response shape from Keycloak.
 */
export interface DstToken {
  access_token: string
  expires_in: number
  scope: string
}

/**
 * In-memory token cache for DST API authentication.
 *
 * Stores the most recent OAuth2 token with its expiry timestamp.
 * Provides expiry detection and auto-refresh capability.
 */
export class TokenCache {
  private token: DstToken | null = null
  private expiresAt: number | null = null

  /**
   * Store a new token and compute its absolute expiry time.
   * @param t — OAuth2 token response from Keycloak
   */
  store(t: DstToken): void {
    this.token = t
    // expires_in is in seconds from now; convert to epoch ms
    this.expiresAt = Date.now() + t.expires_in * 1000
  }

  /**
   * Get the current cached token, or null if none exists.
   */
  get(): DstToken | null {
    return this.token
  }

  /**
   * Check whether the cached token is expired (or will expire within 5 minutes).
   * Returns true when the token should be refreshed immediately.
   */
  isExpired(): boolean {
    if (!this.expiresAt) return true
    // Auto-refresh threshold: refresh 5 minutes before expiry
    const fiveMinutesMs = 5 * 60 * 1000
    return Date.now() >= this.expiresAt - fiveMinutesMs
  }

  /**
   * Get the absolute expiry timestamp in ms, or null if no token.
   */
  getExpiresAt(): number | null {
    return this.expiresAt
  }

  /**
   * Get the current token, transparently refreshing if expired or missing.
   *
   * If a cached token exists and is still valid (more than 5 minutes from expiry),
   * returns it immediately without calling refreshFn. Otherwise calls refreshFn,
   * stores the result, and returns the new token.
   *
   * @param refreshFn — Async function that fetches a fresh token from Keycloak
   * @returns The current (or newly refreshed) token, or null if refresh fails
   */
  async getWithRefresh(refreshFn: () => Promise<DstToken>): Promise<DstToken | null> {
    // If we have a valid cached token, return it as-is
    const cached = this.get()
    if (cached && !this.isExpired()) {
      return cached
    }

    // Token is missing or near expiry — refresh transparently
    try {
      const fresh = await refreshFn()
      this.store(fresh)
      return fresh
    } catch {
      // If refresh fails and we have an old token, return it anyway
      // (better to use a slightly expired token than fail entirely)
      if (this.token) return this.token
      return null
    }
  }

  /**
   * Clear the cached token (logout).
   */
  clear(): void {
    this.token = null
    this.expiresAt = null
  }
}

/**
 * DST Authentication — OAuth2 password grant for the DST supplier API.
 */

import { TokenCache, type DstToken } from '@/features/dst-auth/services/token-cache.js'

// ============================================================================
// Types
// ============================================================================

export interface DstAuthResult {
  authenticated: boolean
  expiresIn?: number
  scope?: string
}

export interface DstTokenStatus {
  authenticated: boolean
  expiresAt: number | null
}

// ============================================================================
// Module-level singleton cache
// ============================================================================

const cache = new TokenCache()

/** DST Keycloak token endpoint URL */
const TOKEN_URL = 'https://keycloak.platformdst.nl/auth/realms/DST/protocol/openid-connect/token'

let autoAuthAttempted = false

// ============================================================================
// Public API
// ============================================================================

export async function authenticateWithDST(params: {
  username: string
  password: string
}): Promise<DstAuthResult> {
  const { username, password } = params

  try {
    const response = await fetch(TOKEN_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: new URLSearchParams({
        grant_type: 'password',
        username,
        password,
        client_id: 'dst3-api'
      })
    })

    if (!response.ok) {
      const body = await response.text()
      console.error(`[DST Auth] Login failed: ${response.status} ${response.statusText}`)
      console.error(`[DST Auth] Response body: ${body.slice(0, 500)}`)
      return { authenticated: false }
    }

    const tokenData = await response.json() as DstToken
    cache.store(tokenData)

    return {
      authenticated: true,
      expiresIn: tokenData.expires_in,
      scope: tokenData.scope
    }
  } catch (err) {
    console.error('[DST Auth] Authentication failed:', err instanceof Error ? err.message : String(err))
    return { authenticated: false }
  }
}

export function getTokenStatus(): DstTokenStatus {
  const token = cache.get()
  if (!token) {
    return { authenticated: false, expiresAt: null }
  }

  return {
    authenticated: true,
    expiresAt: cache.getExpiresAt()!
  }
}

export function getAccessToken(): string | undefined {
  return cache.get()?.access_token
}

/** Attempt to authenticate using env credentials. Runs at most once per process. */
export async function ensureAuthenticated(): Promise<DstTokenStatus> {
  if (cache.get()) {
    return getTokenStatus()
  }

  if (autoAuthAttempted) {
    return getTokenStatus()
  }

  autoAuthAttempted = true

  const username = process.env.VITE_DST_USERNAME || process.env.DST_USERNAME
  const password = process.env.VITE_DST_PASSWORD || process.env.DST_PASSWORD

  if (!username || !password) {
    console.log('[DST Auth] No DST credentials in env — skipping auto-auth')
    return getTokenStatus()
  }

  try {
    const result = await authenticateWithDST({ username, password })
    if (result.authenticated) {
      console.log('[DST Auth] Auto-authenticated with DST successfully')
    } else {
      console.warn('[DST Auth] Auto-auth failed — credentials may be invalid')
    }
  } catch (err) {
    console.error('[DST Auth] Auto-auth error:', err instanceof Error ? err.message : String(err))
  }

  return getTokenStatus()
}

export function logoutFromDST(): void {
  cache.clear()
}

/**
 * DST Supplier Adapter — Real-time EAN search via DST catalog API.
 *
 * DST returns deeply nested Spring Data JSON:
 *   { content: [ { data.identifiers, data.productinformation.*, ... } ] }
 *
 * This adapter extracts flat offers from that structure and deduplicates
 * by `${ean_upc}-${itemnumber}`, preferring Dutch language variants.
 */

import { db } from '@/db/index.js'
import { supplierProducts } from '@/db/schema.js'
import crypto from 'crypto'
import type { DstOfferRaw, DstPagedResponse, DstProductRaw, SearchResults, SupplierOffer } from '../../../types.js'
import type { SupplierAdapter, SupplierAuthStatus } from '../base.js'
import { ensureAuthenticated, getAccessToken, getTokenStatus } from './auth.js'

// ============================================================================
// Configuration
// ============================================================================

const DST_SEARCH_URL = process.env.DST_SEARCH_API_URL || 'https://dst3-api.platformdst.nl/api/customer'
const VAT_DIVISOR = 1.21

// ============================================================================
// Price calculation helpers
// ============================================================================

function grossEurToNetCents(grossEur: number): number {
  return Math.round((grossEur * 100) / VAT_DIVISOR)
}

// ============================================================================
// DST API client — extracts flat offers from nested JSON
// ============================================================================

/** Map a single deeply-nested DST product into our flat DstOfferRaw shape. */
function mapDSTProduct(product: DstProductRaw): DstOfferRaw | null {
  const d = product.data
  const eanUpc = d.identifiers.ean_upc?.trim()
  if (!eanUpc) return null // skip products without EAN

  const brand = d.productinformation.general_productinformation.brand || undefined
  const model = d.productinformation.general_productinformation.model || undefined
  const name = d.productinformation.descriptions?.short_description ??
    d.identifiers.supplier_description ?? ''
  const imageUrl = d.productinformation.general_productinformation.pos_image?.[0] || undefined
  const recommendedRetailPriceGross = d.productinformation.price_information.recommended_retailprice
  const grossPurchasePriceGross = d.productinformation.price_information.gross_purchase_price

  return {
    eanUpc,
    itemNumber: d.identifiers.itemnumber || '',
    brand,
    model,
    name,
    imageUrl,
    recommendedRetailPriceGross,
    grossPurchasePriceGross,
    suggestedSellPriceNet: recommendedRetailPriceGross
      ? grossEurToNetCents(recommendedRetailPriceGross)
      : undefined,
    suggestedCostPriceNet: grossPurchasePriceGross
      ? grossEurToNetCents(grossPurchasePriceGross)
      : undefined,
    supplierName: d.identifiers.supplier || 'Unknown',
    lang: d.language || undefined
  }
}

/** Search DST by EAN barcode. Returns both flat offers and raw products for caching. */
async function searchByEan(ean: string, token: string): Promise<{ offers: DstOfferRaw[]; rawProducts: DstProductRaw[] }> {
  const url = `${DST_SEARCH_URL}/product?eanUpc=${encodeURIComponent(ean)}&statuses=ACTIVE,OBSOLETE&page=0&size=100`

  const response = await fetch(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/json'
    }
  })

  if (!response.ok) {
    throw new Error(`DST search failed: ${response.status} ${response.statusText}`)
  }

  // DST returns Spring Data Page<T>: { content: [...], pageable, totalPages, ... }
  const data = await response.json() as DstPagedResponse
  const rawProducts = (data.content ?? []) as unknown as DstProductRaw[]

  const offers = rawProducts
    .map(mapDSTProduct)
    .filter((o): o is DstOfferRaw => o !== null)

  return { offers, rawProducts }
}

// DST does not support keyword search — only EAN lookup.
async function _searchByKeywordNotSupported(): Promise<never> {
  throw new Error('DST does not support keyword search. Use EAN-only lookup.')
}

// ============================================================================
// Deduplication logic
// ============================================================================

function makeDedupKey(offer: DstOfferRaw): string {
  const ean = (offer.eanUpc || '').trim()
  const itemNumber = (offer.itemNumber || '').trim()
  return `${ean}-${itemNumber}`
}

function isDutch(lang: string | undefined): boolean {
  return lang === 'nl'
}

/** Deduplicate offers by `${ean_upc}-${itemnumber}`, preferring Dutch variants. */
export function deduplicateOffers(offers: DstOfferRaw[]): SupplierOffer[] {
  const groups = new Map<string, DstOfferRaw[]>()

  for (const offer of offers) {
    const key = makeDedupKey(offer)
    if (!groups.has(key)) {
      groups.set(key, [])
    }
    groups.get(key)!.push(offer)
  }

  const result: SupplierOffer[] = []

  for (const [, variants] of groups) {
    let preferred = variants[0]
    for (const v of variants) {
      if (isDutch(v.lang)) {
        preferred = v
        break
      }
    }

    result.push(mapToSupplierOffer(preferred))
  }

  return result
}

/** Flatten a DstOfferRaw into the final SupplierOffer shape. */
export function mapToSupplierOffer(offer: DstOfferRaw): SupplierOffer {
  return {
    eanUpc: offer.eanUpc || '',
    itemNumber: offer.itemNumber || '',
    brand: offer.brand,
    model: offer.model,
    name: offer.name,
    imageUrl: offer.imageUrl,
    recommendedRetailPriceGross: offer.recommendedRetailPriceGross,
    grossPurchasePriceGross: offer.grossPurchasePriceGross,
    suggestedSellPriceNet:
      offer.suggestedSellPriceNet ??
      (offer.recommendedRetailPriceGross != null
        ? grossEurToNetCents(offer.recommendedRetailPriceGross)
        : undefined),
    suggestedCostPriceNet:
      offer.suggestedCostPriceNet ??
      (offer.grossPurchasePriceGross != null
        ? grossEurToNetCents(offer.grossPurchasePriceGross)
        : undefined),
    supplierName: offer.supplierName,
    lang: offer.lang
  }
}

// ============================================================================
// Supplier product caching — store full nested DstProductRaw tree
// ============================================================================

function generateSupplierProductId(eanUpc: string, supplierName: string): string {
  const hash = crypto.createHash('sha256').update(`${eanUpc}|${supplierName}`).digest('hex').slice(0, 16)
  return `sp-${hash}`
}

/** Cache the full nested DstProductRaw tree — preserves all supplier data for detail queries. */
async function cacheSearchResults(product: DstProductRaw): Promise<void> {
  const eanUpc = product.data.identifiers.ean_upc || ''
  const supplierName = product.data.identifiers.supplier
  if (!eanUpc) return // skip products without EAN

  const id = generateSupplierProductId(eanUpc, supplierName)

  await db.insert(supplierProducts).values({
    id,
    eanUpc: eanUpc || '',
    rawJson: JSON.stringify(product),
    supplierName: supplierName,
    searchedAt: new Date(Date.now())
  }).onConflictDoUpdate({
    target: [supplierProducts.eanUpc, supplierProducts.supplierName],
    set: {
      rawJson: JSON.stringify(product),
      searchedAt: new Date(Date.now())
    }
  })
}

// ============================================================================
// SupplierAdapter Implementation
// ============================================================================

export const dstAdapter: SupplierAdapter = {
  id: 'dst',
  name: 'DST Aggregator',

  isEnabled(): boolean {
    return !!(process.env.VITE_DST_USERNAME || process.env.DST_USERNAME) &&
           !!(process.env.VITE_DST_PASSWORD || process.env.DST_PASSWORD)
  },

  getStatus(): SupplierAuthStatus {
    const status = getTokenStatus()
    return {
      authenticated: status.authenticated,
      expiresAt: status.expiresAt
    }
  },

  async searchByEan(ean: string): Promise<SearchResults> {
    const status = await ensureAuthenticated()
    if (!status.authenticated) {
      return { offers: [] }
    }

    try {
      const accessToken = getAccessToken()
      if (!accessToken) {
        throw new Error('No access token available. Please authenticate with DST first.')
      }

      const { offers, rawProducts } = await searchByEan(ean, accessToken)
      const deduplicated = deduplicateOffers(offers)

      // Cache full nested JSON tree (non-blocking — don't fail if cache fails)
      for (const product of rawProducts) {
        cacheSearchResults(product).catch(err => {
          console.error('[Product Finder] Failed to cache DST search result:', err.message)
        })
      }

      return { offers: deduplicated }
    } catch (err) {
      console.error('[DST Adapter] EAN search failed:', err instanceof Error ? err.message : String(err))
      throw new Error(`Search failed: ${err instanceof Error ? err.message : 'Unknown error'}`)
    }
  },

  async searchByKeyword(): Promise<never> {
    // DST does not support keyword search — only EAN lookup.
    return _searchByKeywordNotSupported()
  }
}

/**
 * Product Finder Routes — Per-supplier search, combined search, and import endpoints.
 *
 * GET  /product-finder/search?ean=XXX&supplier=dst          — EAN search for specific supplier
 * GET  /product-finder/search?q=keyword&supplier=kruitbosch — Keyword search for specific supplier
 * GET  /product-finder/search/all?ean=XXX                   — Search all suppliers (combined)
 * POST /product-finder/sync/:supplier                       — Sync catalog from a supplier
 * POST /product-finder/import                               — Import product into local catalog
 * GET  /product-finder/suppliers                            — List available suppliers
 */

import { Hono } from 'hono'
import {
  searchSupplierByEan,
  searchSupplierByKeyword,
  searchAllByEan,
  searchAllByKeyword,
  syncSupplier,
  getAuthStatus
} from '../features/product-finder/services/search-service.js'
import { importProduct } from '../features/product-finder/services/import-service.js'
import { getSupplierList } from '../features/product-finder/services/suppliers/index.js'
import { getDstDetail } from '../features/product-finder/services/suppliers/dst/detail-service.js'
import { getKruitboschDetail } from '../features/product-finder/services/suppliers/kruitbosch/detail-service.js'
import { getGransierDetail } from '../features/product-finder/services/suppliers/gransier/detail-service.js'

// ============================================================================
// GET /search — Per-supplier search (EAN or keyword)
// ============================================================================

const productFinderRoutes = new Hono()

productFinderRoutes.get('/search', async (c) => {
  const ean = c.req.query('ean')
  const q = c.req.query('q')
  const supplier = c.req.query('supplier') || 'dst' // default to dst for backward compat
  const page = parseInt(c.req.query('page') || '0', 10)
  const size = parseInt(c.req.query('size') || '20', 10)

  if (!ean && !q) {
    return c.json({ error: 'Provide either "ean" (exact match) or "q" (keyword search)' }, 400)
  }

  try {
    let result

    if (ean) {
      result = await searchSupplierByEan(supplier, ean)
    } else {
      result = await searchSupplierByKeyword(supplier, q!, page, size)
    }

    return c.json(result)
  } catch (err) {
    console.error('[GET /product-finder/search] Error:', err instanceof Error ? err.message : String(err))
    const status = getAuthStatus()
    if (!status.authenticated) {
      return c.json({ error: 'Not authenticated. Please log in to DST first.', offers: [] }, 401)
    }
    return c.json({ error: 'Search failed', offers: [], pagination: null }, 500)
  }
})

// ============================================================================
// GET /search/all — Combined search across all suppliers
// ============================================================================

productFinderRoutes.get('/search/all', async (c) => {
  const ean = c.req.query('ean')
  const q = c.req.query('q')
  const page = parseInt(c.req.query('page') || '0', 10)
  const size = parseInt(c.req.query('size') || '20', 10)

  if (!ean && !q) {
    return c.json({ error: 'Provide either "ean" (exact match) or "q" (keyword search)' }, 400)
  }

  try {
    let result

    if (ean) {
      result = await searchAllByEan(ean)
    } else {
      result = await searchAllByKeyword(q!, page, size)
    }

    return c.json(result)
  } catch (err) {
    console.error('[GET /product-finder/search/all] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Search failed', offers: [], pagination: null }, 500)
  }
})

// ============================================================================
// POST /sync/:supplier — Sync catalog from a supplier (e.g. Kruitbosch)
// ============================================================================

productFinderRoutes.post('/sync/:supplier', async (c) => {
  const supplierId = c.req.param('supplier')

  try {
    const result = await syncSupplier(supplierId)
    return c.json(result)
  } catch (err) {
    console.error(`[POST /product-finder/sync/${supplierId}] Error:`, err instanceof Error ? err.message : String(err))
    return c.json({ success: false, importedCount: 0, error: err instanceof Error ? err.message : 'Unknown error' }, 500)
  }
})

// ============================================================================
// GET /suppliers — List available suppliers (async, includes sync status)
// ============================================================================

productFinderRoutes.get('/suppliers', async (c) => {
  const list = await getSupplierList()
  return c.json({ suppliers: list })
})

// ============================================================================
// POST /import — Import product into local catalog
// ============================================================================

interface ImportRequest {
  eanUpc: string
  name: string
  sellPrice: number
  costPrice: number
  supplierName: string
  quantityOnHand?: number
}

productFinderRoutes.post('/import', async (c) => {
  try {
    const body = await c.req.json() as ImportRequest

    if (!body.eanUpc || !body.name || body.sellPrice == null || body.costPrice == null || !body.supplierName) {
      return c.json({ success: false, action: 'updated', message: 'Missing required fields: eanUpc, name, sellPrice, costPrice, supplierName' }, 400)
    }

    // Validate quantityOnHand if provided
    if (body.quantityOnHand != null && (!Number.isInteger(body.quantityOnHand) || body.quantityOnHand < 0)) {
      return c.json({ success: false, action: 'updated', message: 'quantityOnHand must be a non-negative integer' }, 400)
    }

    const result = await importProduct(body)

    if (!result.success) {
      return c.json(result, 422)
    }

    return c.json(result, 200)
  } catch (err) {
    console.error('[POST /product-finder/import] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ success: false, action: 'updated', message: `Import failed: ${err instanceof Error ? err.message : 'Unknown error'}` }, 500)
  }
})

// ============================================================================
// GET /auth/status — Authentication status (legacy endpoint)
// ============================================================================

productFinderRoutes.get('/auth/status', (c) => {
  const status = getAuthStatus()
  return c.json(status)
})

// ============================================================================
// GET /kruitbosch/detail?ean=XXX — Kruitbosch product detail endpoint
// ===========================================================================

productFinderRoutes.get('/kruitbosch/detail', async (c) => {
  const ean = c.req.query('ean')

  if (!ean || !ean.trim()) {
    return c.json({ error: 'Missing or empty "ean" query parameter' }, 404)
  }

  try {
    const detail = await getKruitboschDetail(ean)

    if (!detail) {
      return c.json(
        { error: `Product not found in Kruitbosch catalog for EAN: ${ean.trim()}` },
        404
      )
    }

    return c.json(detail, 200)
  } catch (err) {
    console.error('[GET /product-finder/kruitbosch/detail] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Internal server error while fetching product detail' }, 500)
  }
})

// ============================================================================
// GET /gransier/detail?ean=XXX — Gransier product detail endpoint
// ===========================================================================

productFinderRoutes.get('/gransier/detail', async (c) => {
  const ean = c.req.query('ean')

  if (!ean || !ean.trim()) {
    return c.json({ error: 'Missing or empty "ean" query parameter' }, 404)
  }

  try {
    const detail = await getGransierDetail(ean)

    if (!detail) {
      return c.json(
        { error: `Product not found in Gransier catalog for EAN: ${ean.trim()}` },
        404
      )
    }

    return c.json(detail, 200)
  } catch (err) {
    console.error('[GET /product-finder/gransier/detail] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Internal server error while fetching product detail' }, 500)
  }
})

// ============================================================================
// GET /dst/detail?ean=XXX — DST product detail endpoint
// ===========================================================================

productFinderRoutes.get('/dst/detail', async (c) => {
  const ean = c.req.query('ean')

  if (!ean || !ean.trim()) {
    return c.json({ error: 'Missing or empty "ean" query parameter' }, 404)
  }

  try {
    const detail = await getDstDetail(ean)

    if (!detail) {
      return c.json(
        { error: `Product not found in DST catalog for EAN: ${ean.trim()}` },
        404
      )
    }

    return c.json(detail, 200)
  } catch (err) {
    console.error('[GET /product-finder/dst/detail] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Internal server error while fetching product detail' }, 500)
  }
})

export default productFinderRoutes

/**
 * Product Finder — Dedicated page for supplier search and import.
 *
 * Route: /products/dst-search
 */

import { useState, useCallback, useEffect } from 'react'
import { SearchBar } from '../components/SearchBar.js'
import { SearchResultsTable } from '../components/SearchResultsTable.js'
import { ImportReviewModal } from '../components/ImportReviewModal.js'
import {
  searchByEan,
  searchByKeyword,
  syncSupplier,
  importProduct,
  getSuppliers,
  fetchDstDetail,
  fetchKruitboschDetail,
  fetchGransierDetail
} from '../services/api.js'
import type { SupplierOffer, ImportRequest, ImportResult, PaginationInfo, SupplierInfo, ProductDetail } from '../types.js'
import { computeFreshness, getFreshnessColorClass, getFreshnessTooltip } from '../utils/freshness.js'

type ActiveTab = 'dst' | 'kruitbosch' | 'gransier'

export function ProductFinderPage() {
  const [activeTab, setActiveTab] = useState<ActiveTab>('dst')
  const [offers, setOffers] = useState<SupplierOffer[]>([])
  const [pagination, setPagination] = useState<PaginationInfo | null>(null)
  const [lastQuery, setLastQuery] = useState<string>('')
  const [isLoading, setIsLoading] = useState(false)
  const [isImporting, setIsImporting] = useState(false)
  const [isSyncing, setIsSyncing] = useState(false)
  const [selectedOffer, setSelectedOffer] = useState<SupplierOffer | null>(null)
  const [importResult, setImportResult] = useState<ImportResult | null>(null)
  const [syncFeedback, setSyncFeedback] = useState<{ success: boolean; importedCount?: number; error?: string } | null>(null)
  const [suppliers, setSuppliers] = useState<SupplierInfo[]>([])

  // Load supplier list on mount
  useEffect(() => {
    getSuppliers()
      .then(data => setSuppliers(data.suppliers))
      .catch(() => {})
  }, [])

  // Enabled status helpers — used for disabling tabs and sync buttons
  const dstEnabled = suppliers.find(s => s.id === 'dst')?.enabled ?? false
  const kruitboschEnabled = suppliers.find(s => s.id === 'kruitbosch')?.enabled ?? false
  const gransierEnabled = suppliers.find(s => s.id === 'gransier')?.enabled ?? false

  // Freshness helpers — compute status for each supplier tab
  const getTabFreshness = useCallback((supplierId: string) => {
    const supplier = suppliers.find(s => s.id === supplierId)
    if (!supplier) return { colorClass: 'bg-red-500', tooltip: 'Unknown' }

    // DST uses auth status instead of sync timestamp
    if (supplierId === 'dst') {
      if (supplier.authStatus?.authenticated) {
